style.css:
/* Fondo principal con CR7 en blanco y negro *//* Fondo con CR7 en blanco y negro */
body {
    background: url("https://i.imgur.com/3nq0gVj.png") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #FFD700 !important; /* Letras doradas */
}

/* Fondos de elementos principales más oscuros */
div, section {
    background-color: rgba(0,0,0,0.8) !important;
    color: #FFD700 !important;
}

/* Texto de enlaces y botones dorado */
a, button, span {
    color: #FFD700 !important;
}
